  "steps": [
    {
      "id": 1,
      "claim": "The bystander's prior statement to a friend is inconsistent with his in‑court testimony that the light was red.",
      "evidence": "Current testimony: light was red; prior statement: \"I was not sure if the signal was yellow or red.\"",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "A prior inconsistent statement that was not made under oath is not admissible as substantive evidence because, if offered for the truth of the matter asserted, it is hearsay without an exception.",
      "evidence": "FRE 801(d)(1)(A): prior inconsistent statements are admissible as substantive evidence only if made under penalty of perjury at a trial, hearing, or deposition.",
      "weight": 0.30,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The same prior inconsistent statement is admissible for the limited purpose of impeaching the witness’s credibility.",
      "evidence": "FRE 613 allows a party to attack a witness’s credibility with prior inconsistent statements, regardless of whether the statement was under oath.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "No other hearsay or substantive‑evidence exception applies to the statement (it is not a party admission, present‑sense impression, etc.).",
      "evidence": "The witness is a lay bystander, not a party; the statement was casual, not under oath, and does not fit any recognized exception.",
      "weight": 0.10,
      "depends_on": [2]
    },
    {
      "id": 5,
      "claim": "Therefore, the trial judge should, upon request by the plaintiff, give a limiting instruction that the prior statement may be used only to impeach the witness’s credibility and not as substantive evidence.",
      "evidence": "FRE 105 requires a limiting instruction when evidence is admissible for one purpose (impeachment) but not another (substantive proof). The plaintiff, who called the witness, is the party most likely to request the instruction.",
      "weight": 0.15,
      "depends_on": [2, 3, 4]
    }
  ],
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Would allow the prior statement as substantive evidence, violating the hearsay rule because the statement was not made under oath and lacks any other exception."
    },
    {
      "answer": "B",
      "reason_rejected": "Calling additional witnesses to prove the statement was made is unnecessary; the statement’s admissibility and purpose are already governed by FRE 613 and 105."
    },
    {
      "answer": "C",
      "reason_rejected": "Disregarding the bystander's testimony altogether is too drastic; the testimony is admissible, only its credibility is in question."
    }
  ]
}
